#[inline]
pub fn rp_hex_digits() -> Str {
    str_lit!("0123456789abcdef")
}

/// Bytes `b` from `i` on, two hexadecimal digits each.
pub fn rp_hex_of(b: Bytes, i: Int) -> Str {
    if _gt_eq(i, bytevector_length(b)) {
        str_lit!("")
    } else {
        let k = u8_to_int(bytevector_u8_ref(b, i));
        string_append(substring(rp_hex_digits(), quotient(k, int_lit(16)), _plus(quotient(k, int_lit(16)), int_lit(1))), string_append(substring(rp_hex_digits(), remainder(k, int_lit(16)), _plus(remainder(k, int_lit(16)), int_lit(1))), rp_hex_of(b, _plus(i, int_lit(1)))))
    }
}

// Importing: a rep's nodes, as `rep-nodes` gives them, back to a type of the
// checker's (C301). Each node by its slot; a bound variable by its binder's
// name at its place; a hole by its name; a node met again while it is being
// made, a recursive type's variable, `%mN`, its node then a `%mu`.
pub type RpIn = Product_11_12<RpNodes, List<Symbol>>;

pub fn rp_node_at(mut ns: RpNodes, mut k: Int) -> RpNodes {
    loop {
        if null_p(ns) {
            return nil::<Product_11_12_13_14_15<Int, Symbol, bool, List<Symbol>, List<kayak_rt::Sum>>>();
        } else if _eq(car(ns).0, k) {
            return kayak_rt::heap_cons(car(ns), kayak_rt::nil());
        } else {
            ns = cdr(ns);
            continue;
        }
    }
}

pub fn nth_symbol(mut xs: List<Symbol>, mut k: Int) -> Str {
    loop {
        if null_p(xs) {
            return str_lit!("?");
        } else if _eq(k, int_lit(0)) {
            return symbol_to_string(car(xs));
        } else {
            (xs, k) = (cdr(xs), _minus(k, int_lit(1)));
            continue;
        }
    }
}

pub fn drop_sexps(mut xs: Sexps, mut n: i64) -> Sexps {
    loop {
        if (null_p(xs) || i64_lt_eq(n, 0i64)) {
            return xs;
        } else {
            (xs, n) = (cdr(xs), i64_minus(n, 1i64));
            continue;
        }
    }
}

pub fn drop_n(mut xs: RpOperands, mut n: i64) -> RpOperands {
    loop {
        if (null_p(xs) || i64_lt_eq(n, 0i64)) {
            return xs;
        } else {
            (xs, n) = (cdr(xs), i64_minus(n, 1i64));
            continue;
        }
    }
}

// A specification's text back, as the checker writes it (C303), from its
// nodes: `(spec (p …) r requires ensures)`.
pub fn rp_op_text(mut ns: RpNodes, mut a: RpOperand) -> Str {
    loop {
        let tagcase_ = a;
        let tag_ = kayak_rt::sum_tag(tagcase_);
        if tag_ == const { kayak_rt::tag_hash("int") } {
            let k: Int = kayak_rt::sum_payload::<Int>(tagcase_);
            return int_to_string(k);
        } else if tag_ == const { kayak_rt::tag_hash("sym") } {
            let n: Symbol = kayak_rt::sum_payload::<Symbol>(tagcase_);
            return symbol_to_string(n);
        } else if tag_ == const { kayak_rt::tag_hash("node") } {
            let j: Int = kayak_rt::sum_payload::<Int>(tagcase_);
            let n = rp_node_at(ns, j);
            if null_p(n) {
                return str_lit!("?");
            } else {
                let h = symbol_to_string(car(n).1);
                let args = car(n).4;
                let words = kayak_rt::closure1s((ns, args,), |(ns, args,), name: Str| {
                    string_append(str_lit!("("), string_append(name, string_append(rp_ops_text(ns, args), str_lit!(")"))))
                });
                if string_eq_p(h, str_lit!("atom")) {
                    a = car(args);
                    continue;
                } else if string_eq_p(h, str_lit!("param")) {
                    return words.call(str_lit!("p"));
                } else if string_eq_p(h, str_lit!("result")) {
                    return str_lit!("(res)");
                } else if string_eq_p(h, str_lit!("length")) {
                    return words.call(str_lit!("len"));
                } else if string_eq_p(h, str_lit!("nat")) {
                    return words.call(str_lit!("natp"));
                } else if string_eq_p(h, str_lit!("rel")) {
                    return string_append(str_lit!("(rel "), string_append(i64_to_string(rp_index_of(rp_rels(), {
                        let tagcase_ = car(args);
                        let tag_ = kayak_rt::sum_tag(tagcase_);
                        if tag_ == const { kayak_rt::tag_hash("sym") } {
                            let n: Symbol = kayak_rt::sum_payload::<Symbol>(tagcase_);
                            symbol_to_string(n)
                        } else {
                            let other = tagcase_;
                            str_lit!("")
                        }
                    }, 0i64)), string_append(rp_ops_text(ns, cdr(args)), str_lit!(")"))));
                } else if string_eq_p(h, str_lit!("shape")) {
                    return string_append(str_lit!("(shape "), string_append(rp_op_text(ns, car(args)), string_append(str_lit!(" "), string_append(rp_nth_string(rp_shapes(), {
                        let tagcase_ = car(cdr(args));
                        let tag_ = kayak_rt::sum_tag(tagcase_);
                        if tag_ == const { kayak_rt::tag_hash("int") } {
                            let k: Int = kayak_rt::sum_payload::<Int>(tagcase_);
                            int_to_i64(k)
                        } else {
                            let other = tagcase_;
                            -1i64
                        }
                    }), str_lit!(")")))));
                } else {
                    return words.call(h);
                }
            }
        } else {
            let other = tagcase_;
            return str_lit!("?");
        }
    }
}

#[inline]
pub fn rp_ops_text(ns: RpNodes, r#as: RpOperands) -> Str {
    if null_p(r#as) {
        str_lit!("")
    } else {
        string_append(str_lit!(" "), string_append(rp_op_text(ns, car(r#as)), rp_ops_text(ns, cdr(r#as))))
    }
}

pub fn rp_spec_text(ns: RpNodes, j: Int) -> Str {
    let n = car(rp_node_at(ns, j));
    let bs = map(kayak_rt::as_proc(kayak_rt::closure1s((), |(), b: Symbol| {
        if string_eq_p(symbol_to_string(b), str_lit!("")) {
            str_lit!("%none")
        } else {
            symbol_to_string(b)
        }
    })), n.3);
    let args = n.4;
    string_append(str_lit!("(spec ("), string_append(words_of(reverse(cdr(reverse(bs)))), string_append(str_lit!(") "), string_append(last(bs), string_append(rp_ops_text(ns, args), str_lit!(")"))))))
}

// What an import is in: the rep's nodes; its holes' names; the binders in
// scope, each its node's slot and its names; the nodes being made.
#[derive(Clone, Copy)]
pub enum Ri {
    Ri(RpNodes, List<Symbol>, List<Product_11_12<Int, List<Symbol>>>, List<Int>),
}

impl kayak_rt::data::Variant<0> for Ri {
    type Fields = (RpNodes, List<Symbol>, List<Product_11_12<Int, List<Symbol>>>, List<Int>,);
    #[inline(always)]
    fn tag() -> &'static kayak_rt::SymObj {
        kayak_rt::tag_lit!("ri")
    }
}

#[allow(non_snake_case)]
impl Ri {
    #[inline(always)]
    pub fn __is_Ri(w: kayak_rt::data::DataAt<'_, Self>) -> bool {
        w.is::<0>()
    }
    #[inline(always)]
    pub fn __Ri(w: kayak_rt::data::DataAt<'_, Self>) -> <Self as kayak_rt::data::Variant<0>>::Fields {
        w.fields::<0>()
    }
}

impl kayak_rt::data::Datatype for Ri {
    #[inline]
    fn read(w: kayak_rt::data::DataAt<'_, Self>) -> Self {
        if w.is::<0>() {
            let (f0, f1, f2, f3,) = w.fields::<0>();
            Self::Ri(f0, f1, f2, f3)
        } else {
            kayak_rt::data::no_variant()
        }
    }
    fn reach<'a>(w: kayak_rt::data::DataAt<'a, Self>, t: &mut kayak_rt::Tracer<'a>) where Self: 'a {
        if w.is::<0>() { return t.reach(w.obj::<0>()); }
    }
    fn object(w: kayak_rt::data::DataAt<'static, Self>) -> &'static dyn kayak_rt::value::Obj where Self: 'static {
        if w.is::<0>() { return (w.obj::<0>()); }
        let _ = w;
        kayak_rt::data::no_variant()
    }
    fn of_object(o: &'static dyn kayak_rt::value::Obj) -> ::core::option::Option<kayak_rt::data::DataAt<'static, Self>> where Self: 'static {
        if let ::core::option::Option::Some(x) = kayak_rt::data::data_of_object::<Self, 0>(o) { return ::core::option::Option::Some(x); }
        ::core::option::Option::None
    }
}

pub fn ri(f0: RpNodes, f1: List<Symbol>, f2: List<Product_11_12<Int, List<Symbol>>>, f3: List<Int>) -> kayak_rt::data::DataAt<'static, Ri> {
    kayak_rt::data::data_heap::<Ri, 0>((f0, f1, f2, f3,))
}

pub fn ri_binder_names(mut bs: List<Product_11_12<Int, List<Symbol>>>, mut slot: Int) -> List<Symbol> {
    loop {
        if null_p(bs) {
            return nil::<Symbol>();
        } else if _eq(car(bs).0, slot) {
            return car(bs).1;
        } else {
            bs = cdr(bs);
            continue;
        }
    }
}

/// Whether union node `k` is `datum`'s (`rx-datum`).
pub fn ri_datum_p(ns: RpNodes, k: Int, args: RpOperands) -> bool {
    (i64_eq(size(args), 10i64) && {
        let tagcase_ = car(drop_n(args, 7i64));
        let tag_ = kayak_rt::sum_tag(tagcase_);
        if tag_ == const { kayak_rt::tag_hash("node") } {
            let j: Int = kayak_rt::sum_payload::<Int>(tagcase_);
            let n = rp_node_at(ns, j);
            (not(null_p(n)) && string_eq_p(symbol_to_string(car(n).1), str_lit!("pairof")) && {
                let tagcase_ = car(car(n).4);
                let tag_ = kayak_rt::sum_tag(tagcase_);
                if tag_ == const { kayak_rt::tag_hash("node") } {
                    let m: Int = kayak_rt::sum_payload::<Int>(tagcase_);
                    _eq(m, k)
                } else {
                    let other = tagcase_;
                    false
                }
            })
        } else {
            let other = tagcase_;
            false
        }
    })
}

/// A kind node as kayak's checker spells the kind: an arrow `(=> (K …) R)`.
pub fn ri_kind_text(ns: RpNodes, n: RpNode) -> Str {
    let (h, r#as) = (symbol_to_string(n.1), n.4);
    if (string_eq_p(h, str_lit!("=>")) && not(null_p(r#as))) {
        let ks = map(kayak_rt::as_proc(kayak_rt::closure1s((ns,), |(ns,), a: RpOperand| {
            let tagcase_ = a;
            let tag_ = kayak_rt::sum_tag(tagcase_);
            if tag_ == const { kayak_rt::tag_hash("node") } {
                let j: Int = kayak_rt::sum_payload::<Int>(tagcase_);
                let m = rp_node_at(ns, j);
                if null_p(m) {
                    str_lit!("?")
                } else {
                    ri_kind_text(ns, car(m))
                }
            } else {
                let other = tagcase_;
                str_lit!("?")
            }
        })), r#as);
        string_append(str_lit!("(=> ("), string_append(words_of(reverse(cdr(reverse(ks)))), string_append(str_lit!(") "), string_append(last(ks), str_lit!(")")))))
    } else {
        h
    }
}

/// A `named` node's operands, its `gendef` left out.
pub fn rp_gendef_dropped(ns: RpNodes, args: RpOperands) -> RpOperands {
    if (null_p(args) || null_p(cdr(args))) {
        args
    } else {
        let tagcase_ = car(cdr(args));
        let tag_ = kayak_rt::sum_tag(tagcase_);
        if tag_ == const { kayak_rt::tag_hash("node") } {
            let j: Int = kayak_rt::sum_payload::<Int>(tagcase_);
            let n = rp_node_at(ns, j);
            if (not(null_p(n)) && string_eq_p(symbol_to_string(car(n).1), str_lit!("gendef"))) {
                kayak_rt::heap_cons(car(args), cdr(cdr(args)))
            } else {
                args
            }
        } else {
            let other = tagcase_;
            args
        }
    }
}

/// A `poly`'s or `dlambda`'s binders, at node `k`, each spelt as kayak's
/// checker spells one (C346): its kind's mark (`binder-named`), `@` and
/// the node, so that two binders of one name are two, and `%d` if
/// distinct.
pub fn ri_binders_spelt(ns: RpNodes, k: Int, bs: List<Symbol>, r#as: RpOperands) -> List<Symbol> {
    if (null_p(bs) || null_p(r#as)) {
        nil::<Symbol>()
    } else {
        let bn = {
            let tagcase_ = car(r#as);
            let tag_ = kayak_rt::sum_tag(tagcase_);
            if tag_ == const { kayak_rt::tag_hash("node") } {
                let j: Int = kayak_rt::sum_payload::<Int>(tagcase_);
                rp_node_at(ns, j)
            } else {
                let other = tagcase_;
                nil::<Product_11_12_13_14_15<Int, Symbol, bool, List<Symbol>, List<kayak_rt::Sum>>>()
            }
        };
        let kn = if null_p(bn) {
            nil::<Product_11_12_13_14_15<Int, Symbol, bool, List<Symbol>, List<kayak_rt::Sum>>>()
        } else {
            let tagcase_ = car(car(bn).4);
            let tag_ = kayak_rt::sum_tag(tagcase_);
            if tag_ == const { kayak_rt::tag_hash("node") } {
                let j: Int = kayak_rt::sum_payload::<Int>(tagcase_);
                rp_node_at(ns, j)
            } else {
                let other = tagcase_;
                nil::<Product_11_12_13_14_15<Int, Symbol, bool, List<Symbol>, List<kayak_rt::Sum>>>()
            }
        };
        let kind = if null_p(kn) {
            str_lit!("type")
        } else {
            ri_kind_text(ns, car(kn))
        };
        let distinct = (not(null_p(bn)) && not(null_p(cdr(car(bn).4))) && {
            let tagcase_ = car(cdr(car(bn).4));
            let tag_ = kayak_rt::sum_tag(tagcase_);
            if tag_ == const { kayak_rt::tag_hash("flag") } {
                let f: bool = kayak_rt::sum_payload::<bool>(tagcase_);
                f
            } else {
                let other = tagcase_;
                false
            }
        });
        kayak_rt::heap_cons(string_to_symbol(string_append(binder_named(kind, symbol_to_string(car(bs))), string_append(str_lit!("@r"), string_append(int_to_string(k), if distinct {
            str_lit!("%d")
        } else if string_eq_p(kind, str_lit!("place")) {
            str_lit!("%p")
        } else {
            str_lit!("")
        })))), ri_binders_spelt(ns, k, cdr(bs), cdr(r#as)))
    }
}

pub fn ri_ty(c: kayak_rt::data::DataAt<'static, Ri>, a: RpOperand) -> kayak_rt::data::DataAt<'static, Ty> {
    let tagcase_ = c;
    if Ri::__is_Ri(tagcase_) {
        let (ns, hs, bs, busy,) = Ri::__Ri(tagcase_);
        let tagcase_ = a;
        let tag_ = kayak_rt::sum_tag(tagcase_);
        if tag_ == const { kayak_rt::tag_hash("node") } {
            let k: Int = kayak_rt::sum_payload::<Int>(tagcase_);
            if any_p(kayak_rt::as_proc(kayak_rt::closure1s((k,), |(k,), b: Int| {
                _eq(b, k)
            })), busy) {
                ty_var(string_append(str_lit!("%m"), int_to_string(k)))
            } else {
                ri_node(c, k)
            }
        } else if tag_ == const { kayak_rt::tag_hash("bound") } {
            let p: Product_11_12<Int, Int> = kayak_rt::sum_payload::<Product_11_12<Int, Int>>(tagcase_);
            let n = nth_symbol(ri_binder_names(bs, p.0), p.1);
            if has_prefix_p(n, str_lit!("rp..")) {
                ty_data(n, nil::<kayak_rt::data::DataAt<'static, Ty>>())
            } else {
                ty_var(n)
            }
        } else if tag_ == const { kayak_rt::tag_hash("hole") } {
            let h: Int = kayak_rt::sum_payload::<Int>(tagcase_);
            ty_var(nth_symbol(hs, h))
        } else {
            let other = tagcase_;
            ty_void()
        }
    } else { kayak_rt::data::no_variant() }
}

#[inline]
pub fn ri_tys(c: kayak_rt::data::DataAt<'static, Ri>, r#as: RpOperands) -> Tys {
    if null_p(r#as) {
        nil::<kayak_rt::data::DataAt<'static, Ty>>()
    } else {
        kayak_rt::heap_cons(ri_ty(c, car(r#as)), ri_tys(c, cdr(r#as)))
    }
}

/// Descriptions back: `(d-region R)` a region, `(d-type T)` a type.
pub fn ri_descs(c: kayak_rt::data::DataAt<'static, Ri>, r#as: RpOperands) -> Tys {
    if null_p(r#as) {
        nil::<kayak_rt::data::DataAt<'static, Ty>>()
    } else {
        kayak_rt::heap_cons({
            let tagcase_ = car(r#as);
            let tag_ = kayak_rt::sum_tag(tagcase_);
            if tag_ == const { kayak_rt::tag_hash("node") } {
                let k: Int = kayak_rt::sum_payload::<Int>(tagcase_);
                let n = rp_node_at({
                    let tagcase_ = c;
                    if Ri::__is_Ri(tagcase_) {
                        let (ns, hs, bs, busy,) = Ri::__Ri(tagcase_);
                        ns
                    } else { kayak_rt::data::no_variant() }
                }, k);
                if null_p(n) {
                    ty_void()
                } else {
                    if string_eq_p(symbol_to_string(car(n).1), str_lit!("d-region")) {
                        ri_region(c, car(car(n).4))
                    } else if string_eq_p(symbol_to_string(car(n).1), str_lit!("d-size")) {
                        ri_size(c, car(car(n).4))
                    } else if string_eq_p(symbol_to_string(car(n).1), str_lit!("d-effect")) {
                        let tagcase_ = car(car(n).4);
                        let tag_ = kayak_rt::sum_tag(tagcase_);
                        if tag_ == const { kayak_rt::tag_hash("node") } {
                            let j: Int = kayak_rt::sum_payload::<Int>(tagcase_);
                            ty_proc(ri_atoms(c, car(rp_node_at({
                                let tagcase_ = c;
                                if Ri::__is_Ri(tagcase_) {
                                    let (ns, hs, bs, busy,) = Ri::__Ri(tagcase_);
                                    ns
                                } else { kayak_rt::data::no_variant() }
                            }, j)).4), nil::<kayak_rt::data::DataAt<'static, Ty>>(), ty_unit())
                        } else {
                            let other = tagcase_;
                            ty_void()
                        }
                    } else {
                        ri_ty(c, car(car(n).4))
                    }
                }
            } else {
                let other = tagcase_;
                ty_void()
            }
        }, ri_descs(c, cdr(r#as)))
    }
}

/// A size back: `finite`, or a linear one, by `size-of-lin`.
pub fn ri_size(c: kayak_rt::data::DataAt<'static, Ri>, a: RpOperand) -> kayak_rt::data::DataAt<'static, Ty> {
    let tagcase_ = c;
    if Ri::__is_Ri(tagcase_) {
        let (ns, hs, bs, busy,) = Ri::__Ri(tagcase_);
        let tagcase_ = a;
        let tag_ = kayak_rt::sum_tag(tagcase_);
        if tag_ == const { kayak_rt::tag_hash("node") } {
            let k: Int = kayak_rt::sum_payload::<Int>(tagcase_);
            let n = rp_node_at(ns, k);
            if (null_p(n) || not(string_eq_p(symbol_to_string(car(n).1), str_lit!("lin")))) {
                ty_data(str_lit!("%finite"), nil::<kayak_rt::data::DataAt<'static, Ty>>())
            } else {
                let args = car(n).4;
                let k0 = {
                    let tagcase_ = car(args);
                    let tag_ = kayak_rt::sum_tag(tagcase_);
                    if tag_ == const { kayak_rt::tag_hash("int") } {
                        let v: Int = kayak_rt::sum_payload::<Int>(tagcase_);
                        v
                    } else {
                        let other = tagcase_;
                        int_lit(0)
                    }
                };
                let terms = {
                    let tagcase_ = car(cdr(args));
                    let tag_ = kayak_rt::sum_tag(tagcase_);
                    if tag_ == const { kayak_rt::tag_hash("node") } {
                        let j: Int = kayak_rt::sum_payload::<Int>(tagcase_);
                        car(rp_node_at(ns, j)).4
                    } else {
                        let other = tagcase_;
                        nil::<kayak_rt::Sum>()
                    }
                };
                size_of_lin(lin(int_to_i64(k0), map(kayak_rt::as_proc(kayak_rt::closure1s((c, ns,), |(c, ns,), t: RpOperand| {
                    let tagcase_ = t;
                    let tag_ = kayak_rt::sum_tag(tagcase_);
                    if tag_ == const { kayak_rt::tag_hash("node") } {
                        let j: Int = kayak_rt::sum_payload::<Int>(tagcase_);
                        let tn = car(rp_node_at(ns, j)).4;
                        lterm({
                            let tagcase_ = ri_ty(c, car(tn));
                            if Ty::__is_TyVar(tagcase_) {
                                let (v,) = Ty::__TyVar(tagcase_);
                                v
                            } else {
                                let z = tagcase_;
                                str_lit!("?")
                            }
                        }, {
                            let tagcase_ = car(cdr(tn));
                            let tag_ = kayak_rt::sum_tag(tagcase_);
                            if tag_ == const { kayak_rt::tag_hash("int") } {
                                let v: Int = kayak_rt::sum_payload::<Int>(tagcase_);
                                int_to_i64(v)
                            } else {
                                let other = tagcase_;
                                1i64
                            }
                        })
                    } else {
                        let other = tagcase_;
                        lterm(str_lit!("?"), 1i64)
                    }
                })), terms)))
            }
        } else {
            let other = tagcase_;
            ty_data(str_lit!("%finite"), nil::<kayak_rt::data::DataAt<'static, Ty>>())
        }
    } else { kayak_rt::data::no_variant() }
}

pub fn ri_region(c: kayak_rt::data::DataAt<'static, Ri>, a: RpOperand) -> kayak_rt::data::DataAt<'static, Ty> {
    let tagcase_ = c;
    if Ri::__is_Ri(tagcase_) {
        let (ns, hs, bs, busy,) = Ri::__Ri(tagcase_);
        let tagcase_ = a;
        let tag_ = kayak_rt::sum_tag(tagcase_);
        if tag_ == const { kayak_rt::tag_hash("node") } {
            let k: Int = kayak_rt::sum_payload::<Int>(tagcase_);
            let n = rp_node_at(ns, k);
            if null_p(n) {
                ty_void()
            } else {
                let (head, args) = (symbol_to_string(car(n).1), car(n).4);
                if string_eq_p(head, str_lit!("heap")) {
                    ty_rconst(str_lit!("heap"))
                } else if string_eq_p(head, str_lit!("rconst")) {
                    let tagcase_ = car(args);
                    let tag_ = kayak_rt::sum_tag(tagcase_);
                    if tag_ == const { kayak_rt::tag_hash("sym") } {
                        let s: Symbol = kayak_rt::sum_payload::<Symbol>(tagcase_);
                        ty_rconst(symbol_to_string(s))
                    } else {
                        let other = tagcase_;
                        ty_void()
                    }
                } else if string_eq_p(head, str_lit!("frozen")) {
                    let kind = {
                        let tagcase_ = car(args);
                        let tag_ = kayak_rt::sum_tag(tagcase_);
                        if tag_ == const { kayak_rt::tag_hash("flag") } {
                            let f: bool = kayak_rt::sum_payload::<bool>(tagcase_);
                            if f {
                                str_lit!("acyclic")
                            } else {
                                str_lit!("const")
                            }
                        } else {
                            let other = tagcase_;
                            str_lit!("const")
                        }
                    };
                    if null_p(cdr(args)) {
                        ty_rconst(kind)
                    } else {
                        ty_data(str_lit!("%frozen"), kayak_rt::heap_cons(ty_rconst(kind), kayak_rt::heap_cons(ri_ty(c, car(cdr(args))), kayak_rt::nil())))
                    }
                } else {
                    ty_void()
                }
            }
        } else {
            let other = tagcase_;
            ri_ty(c, a)
        }
    } else { kayak_rt::data::no_variant() }
}

